137: function lightLevel(x, y) {
138:   let level = 0.055;
139:   for (const l of LIGHTS) {
140:     const d = dist(x, y, l.x, l.y);
141:     if (d < l.r) {
142:       const v = (1 - d / l.r) * l.intensity;
143:       if (v > level) level = v;
144:     }
145:   }
146:   return clamp(level, 0, 1);
147: }
