149: function hasLOS(x1, y1, x2, y2) {
150:   for (const w of WALLS) {
151:     if (segmentIntersects(x1, y1, x2, y2, w)) return false;
152:   }
153:   for (const p of PROPS) {
154:     if (!p.blockVision) continue;
155:     if (segmentIntersects(x1, y1, x2, y2, p)) return false;
156:   }
157:   return true;
158: }
