160: // local copy to avoid an extra import in hot loops
161: function segmentIntersects(x1, y1, x2, y2, rect) {
162:   if (Math.max(x1, x2) < rect.x || Math.min(x1, x2) > rect.x + rect.w ||
163:       Math.max(y1, y2) < rect.y || Math.min(y1, y2) > rect.y + rect.h) return false;
164:   const dx = x2 - x1, dy = y2 - y1;
165:   const p = [-dx, dx, -dy, dy];
166:   const q = [x1 - rect.x, rect.x + rect.w - x1, y1 - rect.y, rect.y + rect.h - y1];
167:   let t0 = 0, t1 = 1;
168:   for (let i = 0; i < 4; i++) {
169:     if (Math.abs(p[i]) < 1e-9) {
170:       if (q[i] < 0) return false;
171:     } else {
172:       const t = q[i] / p[i];
173:       if (p[i] < 0) {
174:         if (t > t1) return false;
175:         if (t > t0) t0 = t;
176:       } else {
177:         if (t < t0) return false;
178:         if (t < t1) t1 = t;
179:       }
180:     }
181:   }
182:   return true;
183: }
