185: function collides(x, y, r) {
186:   if (x < r || y < r || x > WORLD.w - r || y > WORLD.h - r) return true;
187:   for (const w of WALLS) {
188:     if (x + r > w.x && x - r < w.x + w.w && y + r > w.y && y - r < w.y + w.h) return true;
189:   }
190:   for (const p of PROPS) {
191:     if (!p.solid) continue;
192:     if (x + r > p.x && x - r < p.x + p.w && y + r > p.y && y - r < p.y + p.h) return true;
193:   }
194:   return false;
195: }
