350: function updateCamera(dt) {
351:   const t = state.time;
352:   if (state.attract) {
353:     const tx = 1500 + Math.sin(t * 0.075) * 355;
354:     const ty = 900 + Math.cos(t * 0.052) * 190;
355:     state.camera.x += (tx - state.camera.x) * Math.min(1, dt * 0.7);
356:     state.camera.y += (ty - state.camera.y) * Math.min(1, dt * 0.7);
357:   } else if (state.player) {
358:     const p = state.player;
359:     const lookX = p.moving ? Math.cos(p.angle) * 46 : 0;
360:     const lookY = p.moving ? Math.sin(p.angle) * 46 : 0;
361:     const bias = input.isTouch ? 44 : 0;
362:     const tx = p.x + lookX;
363:     const ty = p.y + lookY + bias;
364:     state.camera.x += (tx - state.camera.x) * Math.min(1, dt * 5.2);
365:     state.camera.y += (ty - state.camera.y) * Math.min(1, dt * 5.2);
366:   }
367:   state.zoom = computeZoom() * (state.attract ? 1.06 : 1);
368:   clampCamera();
