387: // ── player ─────────────────────────────────────────────────────
388: function updatePlayer(dt) {
389:   const p = state.player;
390:   if (!p) return;
391:   p.attackCooldown = Math.max(0, p.attackCooldown - dt);
392:   p.throwCooldown = Math.max(0, p.throwCooldown - dt);
393:   p.swing = Math.max(0, p.swing - dt * 4.2);
394: 
395:   const v = input.vector;
396:   let mx = v.x, my = v.y, mag = v.mag;
397:   if (motion.enabled && motion.magnitude > 0.09 && motion.magnitude > mag) {
398:     mx = motion.x;
399:     my = motion.y;
400:     mag = Math.min(1, motion.magnitude);
401:   }
402: 
403:   p.crouched = input.crouch;
404:   p.sprinting = mag > 0.15 && input.sprinting && !p.crouched && p.stamina > 0.5;
405:   p.moving = mag > 0.12;
406: 
407:   if (p.sprinting) p.stamina = Math.max(0, p.stamina - 27 * dt);
408:   else p.stamina = Math.min(100, p.stamina + 17 * dt);
409: 
410:   if (p.moving) {
411:     const speed = p.sprinting ? 228 : p.crouched ? 83 : 143;
412:     p.angle = angleLerp(p.angle, Math.atan2(my, mx), Math.min(1, dt * 13));
413:     moveEntity(p, mx * speed * dt, my * speed * dt, p.r);
414:     p.walkPhase += dt * (p.sprinting ? 17 : p.crouched ? 7 : 11);
415:     p.stepTimer -= dt;
416:     if (p.stepTimer <= 0) {
417:       p.stepTimer = p.sprinting ? 0.24 : p.crouched ? 0.68 : 0.38;
418:       audio.footstep(p.sprinting ? 'sprint' : p.crouched ? 'crouch' : 'walk');
419:       spawnDust(p.x - Math.cos(p.angle) * 8, p.y - Math.sin(p.angle) * 8, p.sprinting ? 2 : 1);
420:       if (p.sprinting) emitNoise(p.x, p.y, 285, [218, 174, 105], 'sprint');
421:       else if (!p.crouched) emitNoise(p.x, p.y, 92, [168, 162, 137], 'step');
422:     }
423:   } else {
424:     p.stepTimer = Math.min(p.stepTimer, 0.08);
425:   }
426: 
427:   p.hidden = lightLevel(p.x, p.y) < 0.24;
428: 
429:   if (p.health > 0 && p.health < 100 && state.time - p.lastDamage > 12) {
430:     const danger = state.enemies.some(e => e.alive && (e.state === 'chase' || e.state === 'suspicious'));
431:     if (!danger) p.health = Math.min(100, p.health + 1.7 * dt);
432:   }
433: 
434:   if (input.consumeAttack()) playerAttack();
435:   if (input.consumeInteract()) tryInteract();
436:   if (input.consumeThrow()) throwDistraction();
437: 
438:   state.executeTarget = findExecuteTarget();
439:   state.interactTarget = findInteractTarget();
440: }
