442: function findAttackTarget() {
443:   const p = state.player;
444:   const reach = WEAPONS[p.weapon].reach;
445:   let best = null, bestD = reach + 14;
446:   for (const e of state.enemies) {
447:     if (!e.alive) continue;
448:     const d = dist(p.x, p.y, e.x, e.y);
449:     if (d > bestD) continue;
450:     const diff = Math.abs(normAngle(angleTo(p.x, p.y, e.x, e.y) - p.angle));
451:     if (d > 30 && diff > 1.42) continue;
452:     best = e;
453:     bestD = d;
454:   }
455:   return best;
456: }
