458: function canExecute(e) {
459:   const p = state.player;
460:   if (!e.alive || e.state === 'chase' || e.awareness > 0.58) return false;
461:   if (dist(p.x, p.y, e.x, e.y) > 76) return false;
462:   const behind = Math.cos(normAngle(angleTo(e.x, e.y, p.x, p.y) - e.angle));
463:   if (behind > -0.12) return false;
464:   return hasLOS(p.x, p.y, e.x, e.y);
465: }
466: 
467: function findExecuteTarget() {
468:   const p = state.player;
469:   if (!p) return null;
470:   let best = null, bestD = 78;
471:   for (const e of state.enemies) {
472:     if (!e.alive) continue;
473:     const d = dist(p.x, p.y, e.x, e.y);
474:     if (d < bestD && canExecute(e)) { best = e; bestD = d; }
475:   }
476:   return best ? best.id : null;
477: }
