479: function playerAttack() {
480:   const p = state.player;
481:   if (state.mode !== 'playing' || p.attackCooldown > 0 || state.hitStop > 0) return;
482:   const weapon = WEAPONS[p.weapon];
483:   p.attackCooldown = p.weapon === 'bat' || p.weapon === 'cleaver' ? 0.5 : 0.36;
484:   p.swing = 1;
485:   audio.swing();
486: 
487:   const target = findAttackTarget();
488:   if (target && canExecute(target)) {
489:     executeEnemy(target);
490:     return;
491:   }
492: 
493:   if (target) {
494:     target.hp -= weapon.damage;
495:     target.hitFlash = 0.14;
496:     target.state = 'chase';
497:     target.awareness = 1;
498:     target.lostTimer = 0;
499:     target.path = [];
500:     target.pathTimer = 0;
501:     target.lastSeen = { x: p.x, y: p.y };
502:     spawnBlood(target.x, target.y, p.angle, 11);
503:     const a = angleTo(p.x, p.y, target.x, target.y);
504:     moveEntity(target, Math.cos(a) * 12, Math.sin(a) * 12, target.r || 15);
505:     state.shake = Math.max(state.shake, 6);
506:     state.hitStop = Math.max(state.hitStop, 0.045);
507:     audio.hit();
508:     emitNoise(p.x, p.y, weapon.noise, [205, 132, 82], 'hit');
509:     if (target.hp <= 0) killEnemy(target, false);
510:     else triggerAlert(target, true);
511:   } else {
512:     emitNoise(p.x, p.y, weapon.noise * 0.7, [192, 174, 137], 'swing');
513:   }
514: }
