516: function executeEnemy(target) {
517:   const p = state.player;
518:   target.alive = false;
519:   target.state = 'dead';
520:   target.deathAngle = target.angle + (Math.random() - 0.5) * 1.8;
521:   target.hp = 0;
522:   state.kills++;
523:   state.executions++;
524:   p.angle = angleTo(p.x, p.y, target.x, target.y);
525:   spawnBlood(target.x, target.y, p.angle, 34);
526:   spawnBlood(p.x + Math.cos(p.angle) * 20, p.y + Math.sin(p.angle) * 20, p.angle, 9);
527:   state.shake = Math.max(state.shake, 14);
528:   state.hitStop = Math.max(state.hitStop, 0.17);
529:   audio.execute();
530:   flashExecute();
531:   showExecution(target.name);
532:   emitNoise(target.x, target.y, 95, [185, 88, 62], 'execute');
533:   onEnemyKilled(target, true);
534: }
