536: function killEnemy(target, silent) {
537:   if (!target.alive) return;
538:   target.alive = false;
539:   target.state = 'dead';
540:   target.deathAngle = target.angle + (Math.random() - 0.5) * 1.8;
541:   target.hp = 0;
542:   state.kills++;
543:   spawnBlood(target.x, target.y, target.angle, silent ? 18 : 24);
544:   if (!silent) {
