777: // ── hunters ────────────────────────────────────────────────────
778: function canSeePlayer(e) {
779:   const p = state.player;
780:   if (!p) return false;
781:   const d = dist(e.x, e.y, p.x, p.y);
782:   if (d > e.viewDist * 1.25) return false;
783:   const light = lightLevel(p.x, p.y);
784:   let range = e.viewDist * (0.58 + light * 0.58);
785:   if (p.crouched) range *= 0.78;
786:   if (p.sprinting) range *= 1.14;
787:   if (e.state === 'chase') range *= 1.2;
788:   if (d > range) return false;
789:   if (d > 68) {
790:     const dot = (Math.cos(e.angle) * (p.x - e.x) + Math.sin(e.angle) * (p.y - e.y)) / Math.max(1, d);
791:     if (dot < Math.cos(e.fov / 2)) return false;
792:   }
793:   return hasLOS(e.x, e.y, p.x, p.y);
794: }
