796: function setEnemyState(e, next) {
797:   if (e.state === next) return;
798:   e.state = next;
799:   e.path = [];
800:   e.pathTimer = 0;
801:   if (next === 'suspicious') {
802:     e.searchTimer = 0;
803:   } else if (next === 'search') {
804:     e.searchTimer = 0;
805:   } else if (next === 'chase') {
806:     e.lostTimer = 0;
807:     triggerAlert(e);
808:   } else if (next === 'patrol') {
809:     e.awareness = 0;
810:     e.waitTimer = 0.8 + Math.random() * 1.5;
811:   }
812: }
