814: function triggerAlert(e) {
815:   if (state.time - state.lastAlertTime < 2.2) return;
816:   state.lastAlertTime = state.time;
817:   audio.alert();
818:   showToast("YOU'VE BEEN SEEN — <b>BREAK LINE OF SIGHT</b>", 2400);
819: }
