821: function ensurePath(e, tx, ty, force = false) {
822:   if (!force && e.path.length && e.pathTimer > 0) return;
823:   e.path = nav.findPath(e.x, e.y, tx, ty);
824:   e.pathTimer = 0.55 + Math.random() * 0.35;
825: }
826: 
827: function moveAlongPath(e, speed, dt) {
828:   if (!e.path.length) return false;
829:   let node = e.path[0];
830:   if (dist(e.x, e.y, node.x, node.y) < 13) {
831:     e.path.shift();
832:     if (!e.path.length) return false;
833:     node = e.path[0];
834:   }
835:   const a = angleTo(e.x, e.y, node.x, node.y);
836:   const d = dist(e.x, e.y, node.x, node.y);
837:   const step = Math.min(speed * dt, d);
838:   const beforeX = e.x, beforeY = e.y;
839:   moveEntity(e, Math.cos(a) * step, Math.sin(a) * step, e.r || 15);
840:   if (dist(beforeX, beforeY, e.x, e.y) < step * 0.25) e.pathTimer = 0;
841:   e.angle = angleLerp(e.angle, a, Math.min(1, dt * 9));
842:   e.walkPhase += dt * speed * 0.11;
843:   return true;
844: }
