846: function updatePatrol(e, dt, sees) {
847:   const p = state.player;
848:   if (sees) {
849:     e.angle = angleLerp(e.angle, angleTo(e.x, e.y, p.x, p.y), Math.min(1, dt * 5));
850:     if (e.awareness > 0.3) setEnemyState(e, 'suspicious');
851:     return;
852:   }
853:   if (e.waitTimer > 0) {
854:     e.waitTimer -= dt;
855:     e.idleLook += dt;
856:     e.angle += Math.sin(e.idleLook * 1.4) * dt * 0.55;
857:     return;
858:   }
859:   const wp = e.waypoints[e.wpIndex % e.waypoints.length];
860:   if (dist(e.x, e.y, wp[0], wp[1]) < 30) {
861:     e.waitTimer = 1.1 + Math.random() * 2.4;
862:     e.wpIndex = (e.wpIndex + 1) % e.waypoints.length;
863:     e.path = [];
864:     return;
865:   }
866:   if (!e.path.length || e.pathTimer <= 0) ensurePath(e, wp[0], wp[1]);
867:   if (!moveAlongPath(e, e.speed, dt)) {
868:     e.stuckTimer += dt;
869:     if (e.stuckTimer > 1.3) {
870:       e.stuckTimer = 0;
871:       e.waitTimer = 0.2;
872:       e.wpIndex = (e.wpIndex + 1) % e.waypoints.length;
873:       ensurePath(e, e.waypoints[e.wpIndex][0], e.waypoints[e.wpIndex][1], true);
874:     }
875:   } else {
876:     e.stuckTimer = 0;
877:   }
878: }
