880: function updateEnemyAI(e, dt, attract) {
881:   if (!e.alive) return;
882:   e.attackCooldown = Math.max(0, e.attackCooldown - dt);
883:   e.hitFlash = Math.max(0, e.hitFlash - dt);
884:   e.swing = Math.max(0, e.swing - dt * 4);
885:   e.pathTimer = Math.max(0, e.pathTimer - dt);
886: 
887:   if (attract) {
888:     updatePatrol(e, dt, false);
889:     return;
890:   }
891: 
892:   const p = state.player;
893:   const d = dist(e.x, e.y, p.x, p.y);
894:   const sees = canSeePlayer(e);
895: 
896:   if (sees) {
897:     e.lastSeen = { x: p.x, y: p.y };
898:     const light = lightLevel(p.x, p.y);
899:     let rate = 1.15 + (1 - Math.min(1, d / e.viewDist)) * 1.25;
900:     if (p.sprinting) rate *= 1.2;
901:     if (p.crouched) rate *= 0.82;
902:     e.awareness = Math.min(1, e.awareness + dt * rate);
903:     if (e.awareness >= 0.96 && e.state !== 'chase') setEnemyState(e, 'chase');
904:     else if (e.awareness > 0.3 && e.state === 'patrol') setEnemyState(e, 'suspicious');
905:   } else {
906:     e.awareness = Math.max(0, e.awareness - dt * 0.2);
907:   }
908: 
909:   switch (e.state) {
910:     case 'patrol':
911:       updatePatrol(e, dt, sees);
912:       break;
913: 
914:     case 'suspicious': {
915:       e.searchTimer += dt;
916:       if (sees) {
917:         e.angle = angleLerp(e.angle, angleTo(e.x, e.y, p.x, p.y), Math.min(1, dt * 6));
918:         if (e.awareness >= 0.96) { setEnemyState(e, 'chase'); break; }
919:         if (d < 95) { setEnemyState(e, 'chase'); break; }
920:       }
921:       if (!e.path.length || e.pathTimer <= 0) ensurePath(e, e.lastSeen.x, e.lastSeen.y);
922:       moveAlongPath(e, e.speed * 0.58, dt);
923:       if (dist(e.x, e.y, e.lastSeen.x, e.lastSeen.y) < 38) {
924:         e.idleLook += dt;
925:         e.angle += Math.sin(e.idleLook * 1.7) * dt * 1.1;
926:       }
927:       if (!sees && e.searchTimer > 2.8) setEnemyState(e, 'search');
928:       break;
929:     }
930: 
931:     case 'search': {
932:       e.searchTimer += dt;
933:       if (sees) {
934:         e.angle = angleLerp(e.angle, angleTo(e.x, e.y, p.x, p.y), Math.min(1, dt * 7));
935:         if (e.awareness >= 0.96) { setEnemyState(e, 'chase'); break; }
936:       }
937:       const remaining = dist(e.x, e.y, e.lastSeen.x, e.lastSeen.y);
938:       if (remaining > 45) {
939:         if (!e.path.length || e.pathTimer <= 0) ensurePath(e, e.lastSeen.x, e.lastSeen.y);
940:         moveAlongPath(e, e.speed * 0.72, dt);
941:       } else {
942:         e.idleLook += dt;
943:         e.angle += Math.sin(e.idleLook * 1.8) * dt * 1.15;
944:       }
945:       if (e.searchTimer > 6.5) setEnemyState(e, 'patrol');
946:       break;
947:     }
948: 
949:     case 'chase': {
950:       if (sees) {
951:         e.lostTimer = 0;
952:         e.lastSeen = { x: p.x, y: p.y };
953:       } else {
954:         e.lostTimer += dt;
955:       }
956:       if (e.lostTimer > 3.4) {
957:         setEnemyState(e, 'search');
958:         break;
959:       }
960:       if (sees && d < 62) {
961:         e.angle = angleLerp(e.angle, angleTo(e.x, e.y, p.x, p.y), Math.min(1, dt * 12));
962:         if (e.attackCooldown <= 0) enemyAttack(e);
963:         break;
964:       }
965:       if (sees && d < 440) {
966:         const a = angleTo(e.x, e.y, p.x, p.y);
967:         const beforeX = e.x, beforeY = e.y;
968:         moveEntity(e, Math.cos(a) * e.chaseSpeed * dt, Math.sin(a) * e.chaseSpeed * dt, e.r || 15);
969:         e.angle = angleLerp(e.angle, a, Math.min(1, dt * 10));
970:         e.walkPhase += dt * e.chaseSpeed * 0.12;
971:         if (dist(beforeX, beforeY, e.x, e.y) < e.chaseSpeed * dt * 0.3) {
972:           if (!e.path.length || e.pathTimer <= 0) ensurePath(e, p.x, p.y, true);
973:           moveAlongPath(e, e.chaseSpeed, dt);
974:         }
975:       } else {
976:         if (!e.path.length || e.pathTimer <= 0) ensurePath(e, e.lastSeen.x, e.lastSeen.y);
977:         moveAlongPath(e, e.chaseSpeed, dt);
978:         if (!sees && dist(e.x, e.y, e.lastSeen.x, e.lastSeen.y) < 34) {
979:           setEnemyState(e, 'search');
980:         }
981:       }
982:       break;
983:     }
984:   }
985: }
