995: function separateEnemies() {
996:   for (let i = 0; i < state.enemies.length; i++) {
997:     const a = state.enemies[i];
998:     if (!a.alive) continue;
999:     for (let j = i + 1; j < state.enemies.length; j++) {
1000:       const b = state.enemies[j];
1001:       if (!b.alive) continue;
1002:       const dx = b.x - a.x, dy = b.y - a.y;
1003:       const d = Math.hypot(dx, dy);
1004:       const min = (a.r || 15) + (b.r || 15);
1005:       if (d > 0.01 && d < min) {
1006:         const push = (min - d) * 0.5;
1007:         moveEntity(a, -dx / d * push, -dy / d * push, a.r || 15);
1008:         moveEntity(b, dx / d * push, dy / d * push, b.r || 15);
1009:       }
1010:     }
1011:   }
1012: }
