1022:   flashDamage();
1023:   audio.hit();
1024:   spawnBlood(p.x, p.y, angleTo(e.x, e.y, p.x, p.y), 8);
1025:   const a = angleTo(e.x, e.y, p.x, p.y);
1026:   moveEntity(p, Math.cos(a) * 19, Math.sin(a) * 19, p.r);
1027:   if (p.health <= 0) showEnd(false);
1028: }
