1030: // ── HUD / feedback ─────────────────────────────────────────────
1031: function updateHUD(dt = 0) {
1032:   const p = state.player;
1033:   if (!p) return;
1034:   state.hudTimer -= dt;
1035:   if (dt > 0 && state.hudTimer > 0) return;
1036:   state.hudTimer = 0.07;
1037: 
1038:   let anyChase = false, anySus = false, maxAware = 0, alive = 0;
1039:   for (const e of state.enemies) {
1040:     if (!e.alive) continue;
1041:     alive++;
1042:     if (e.state === 'chase') anyChase = true;
1043:     if (e.state === 'suspicious' || e.state === 'search') anySus = true;
1044:     if (e.awareness > maxAware) maxAware = e.awareness;
1045:   }
1046: 
1047:   let threatClass = 'hidden-state';
1048:   let threatText = p.hidden ? 'HIDDEN' : 'UNDETECTED';
1049:   if (anyChase) { threatClass = 'hunted'; threatText = 'HUNTED'; }
1050:   else if (anySus || maxAware > 0.12) { threatClass = 'suspect'; threatText = 'SUSPICIOUS'; }
1051:   dom.threatLabel.className = `threat-label ${threatClass}`;
1052:   dom.threatText.textContent = threatText;
1053:   dom.concealLabel.classList.toggle('on', p.hidden && !anyChase);
1054:   dom.hunterCount.textContent = String(alive);
1055: 
1056:   if (state.exitUnlocked) {
1057:     dom.objectiveText.textContent = 'REACH THE EXTRACTION VAN';
