88:         ctx.strokeStyle = 'rgba(4,6,5,0.26)';
89:         ctx.lineWidth = 0.7;
90:         ctx.beginPath();
91:         ctx.moveTo(x + 9 + h * 40, y + 10);
92:         ctx.lineTo(x + 16 + h2 * 36, y + 26);
93:         ctx.lineTo(x + 10 + h * 50, y + 48);
