98: 
99:   for (const z of ZONES) {
100:     if (!visibleRect(z.x, z.y, z.w, z.h, r)) continue;
101:     ctx.fillStyle = rgb(z.color, z.alpha);
102:     ctx.fillRect(z.x, z.y, z.w, z.h);
103:   }
104: 
105:   if (noisePattern) {
106:     ctx.save();
107:     ctx.globalAlpha = 0.18;
108:     ctx.fillStyle = noisePattern;
109:     ctx.fillRect(b.left, b.top, b.right - b.left, b.bottom - b.top);
110:     ctx.restore();
111:   }
112: 
113:   // broad painted walkway lines
114:   ctx.save();
115:   ctx.strokeStyle = 'rgba(190,170,115,0.06)';
116:   ctx.lineWidth = 5;
117:   ctx.setLineDash([26, 22]);
118:   ctx.beginPath();
119:   ctx.moveTo(420, 1570);
120:   ctx.lineTo(420, 1500);
121:   ctx.lineTo(1450, 1500);
122:   ctx.lineTo(1450, 1435);
123:   ctx.moveTo(1450, 450);
124:   ctx.lineTo(1450, 260);
125:   ctx.lineTo(2200, 260);
126:   ctx.lineTo(2200, 400);
127:   ctx.stroke();
128:   ctx.restore();
