131: export function drawDecals(ctx, state, r) {
132:   for (const d of DECALS) {
133:     if (d.x < r.bounds.left - 220 || d.x > r.bounds.right + 220 || d.y < r.bounds.top - 220 || d.y > r.bounds.bottom + 220) continue;
134:     switch (d.type) {
135:       case 'grime': {
136:         ctx.save();
137:         ctx.translate(d.x, d.y);
138:         ctx.rotate(d.rot);
139:         ctx.fillStyle = `rgba(0,0,0,${d.alpha})`;
140:         ctx.beginPath();
141:         ctx.ellipse(0, 0, d.rx, d.ry, 0, 0, TAU);
142:         ctx.fill();
143:         ctx.restore();
144:         break;
145:       }
146:       case 'stain': {
147:         const g = ctx.createRadialGradient(d.x, d.y, 2, d.x, d.y, d.r);
148:         g.addColorStop(0, rgb(d.color, d.alpha));
149:         g.addColorStop(0.65, rgb(d.color, d.alpha * 0.6));
150:         g.addColorStop(1, rgb(d.color, 0));
151:         ctx.fillStyle = g;
152:         ctx.beginPath();
153:         ctx.arc(d.x, d.y, d.r, 0, TAU);
154:         ctx.fill();
155:         break;
156:       }
157:       case 'puddle': {
158:         ctx.save();
159:         ctx.translate(d.x, d.y);
160:         ctx.rotate(d.rot);
161:         const g = ctx.createLinearGradient(0, -d.ry, 0, d.ry);
162:         g.addColorStop(0, `rgba(122,156,155,${d.alpha * 0.6})`);
163:         g.addColorStop(0.5, `rgba(26,42,42,${d.alpha})`);
164:         g.addColorStop(1, 'rgba(2,5,5,0)');
165:         ctx.fillStyle = g;
166:         ctx.beginPath();
167:         ctx.ellipse(0, 0, d.rx, d.ry, 0, 0, TAU);
168:         ctx.fill();
169:         ctx.strokeStyle = `rgba(174,198,190,${d.alpha * 0.22})`;
170:         ctx.lineWidth = 1;
171:         ctx.stroke();
172:         ctx.restore();
173:         break;
174:       }
175:       case 'blood':
176:         drawBlood(ctx, d);
177:         break;
178:       case 'grate': {
179:         ctx.save();
180:         ctx.translate(d.x, d.y);
181:         ctx.rotate(d.rot);
182:         ctx.fillStyle = 'rgba(3,5,4,0.78)';
183:         ctx.fillRect(0, 0, d.w, d.h);
184:         ctx.strokeStyle = 'rgba(126,130,118,0.25)';
185:         ctx.lineWidth = 2;
186:         for (let i = 6; i < d.w; i += 12) line(ctx, i, 4, i, d.h - 4, 'rgba(126,130,118,0.22)', 2);
187:         ctx.strokeStyle = 'rgba(0,0,0,0.65)';
188:         ctx.lineWidth = 4;
189:         ctx.strokeRect(0, 0, d.w, d.h);
190:         ctx.restore();
191:         break;
192:       }
193:       case 'hazard': {
194:         ctx.save();
195:         ctx.beginPath();
196:         ctx.rect(d.x, d.y, d.w, d.h);
197:         ctx.clip();
198:         ctx.fillStyle = 'rgba(14,14,10,0.55)';
199:         ctx.fillRect(d.x, d.y, d.w, d.h);
200:         for (let i = -d.h; i < d.w + d.h; i += 18) {
201:           ctx.fillStyle = 'rgba(197,157,73,0.34)';
202:           ctx.beginPath();
203:           ctx.moveTo(d.x + i, d.y + d.h);
204:           ctx.lineTo(d.x + i + 9, d.y + d.h);
205:           ctx.lineTo(d.x + i + d.h + 9, d.y);
206:           ctx.lineTo(d.x + i + d.h, d.y);
207:           ctx.closePath();
208:           ctx.fill();
209:         }
210:         ctx.restore();
211:         break;
212:       }
213:       case 'label': {
214:         ctx.save();
215:         ctx.translate(d.x, d.y);
216:         ctx.rotate(d.rot);
217:         ctx.fillStyle = `rgba(208,198,172,${d.alpha})`;
218:         ctx.font = `900 ${d.size}px Impact, "Arial Narrow", sans-serif`;
219:         ctx.textAlign = 'center';
220:         ctx.textBaseline = 'middle';
221:         ctx.fillText(d.text, 0, 0);
222:         ctx.restore();
223:         break;
224:       }
225:     }
226:   }
227: }
