229: function drawBlood(ctx, d) {
230:   const rng = mulberry32(d.seed || 7);
231:   ctx.save();
232:   ctx.translate(d.x, d.y);
233:   ctx.rotate(d.rot);
234:   ctx.scale(d.scale, d.scale);
235:   ctx.fillStyle = 'rgba(52,10,9,0.38)';
236:   for (let i = 0; i < 7; i++) {
237:     const x = (rng() - 0.5) * 42;
238:     const y = (rng() - 0.5) * 30;
239:     const rr = 5 + rng() * 16;
240:     ctx.beginPath();
241:     ctx.ellipse(x, y, rr, rr * (0.55 + rng() * 0.5), rng() * 3, 0, TAU);
242:     ctx.fill();
243:   }
244:   ctx.fillStyle = 'rgba(79,15,12,0.4)';
245:   for (let i = 0; i < 13; i++) {
246:     const a = rng() * TAU, len = 18 + rng() * 62;
247:     ctx.beginPath();
248:     ctx.arc(Math.cos(a) * len, Math.sin(a) * len, 1 + rng() * 4, 0, TAU);
249:     ctx.fill();
250:   }
251:   ctx.strokeStyle = 'rgba(91,20,15,0.3)';
252:   ctx.lineWidth = 1.4;
253:   for (let i = 0; i < 4; i++) {
254:     ctx.beginPath();
255:     ctx.moveTo((rng() - 0.5) * 16, (rng() - 0.5) * 12);
256:     ctx.lineTo((rng() - 0.5) * 74, (rng() - 0.5) * 52);
257:     ctx.stroke();
258:   }
259:   ctx.restore();
260: }
