262: export function drawWalls(ctx, state, r) {
263:   for (const w of WALLS) {
264:     if (!visibleRect(w.x, w.y, w.w, w.h, r)) continue;
265:     const metal = w.style === 'metal';
266:     const outer = w.style === 'outer';
267:     ctx.fillStyle = 'rgba(0,0,0,0.58)';
268:     ctx.fillRect(w.x + 9, w.y + 12, w.w, w.h);
269: 
270:     const g = ctx.createLinearGradient(0, w.y, 0, w.y + w.h);
271:     if (metal) {
272:       g.addColorStop(0, '#46514e');
273:       g.addColorStop(0.22, '#333e3b');
274:       g.addColorStop(1, '#1a2220');
275:     } else if (outer) {
276:       g.addColorStop(0, '#2e3431');
277:       g.addColorStop(1, '#111615');
278:     } else {
279:       g.addColorStop(0, '#4c524f');
280:       g.addColorStop(0.16, '#3c4340');
281:       g.addColorStop(1, '#212825');
282:     }
283:     ctx.fillStyle = g;
284:     ctx.fillRect(w.x, w.y, w.w, w.h);
285: 
286:     ctx.fillStyle = 'rgba(233,227,213,0.2)';
287:     if (w.w >= w.h) ctx.fillRect(w.x + 2, w.y + 2, w.w - 4, 2);
288:     else ctx.fillRect(w.x + 2, w.y + 2, 2, w.h - 4);
289:     ctx.fillStyle = 'rgba(0,0,0,0.34)';
290:     if (w.w >= w.h) ctx.fillRect(w.x, w.y + w.h - 4, w.w, 4);
291:     else ctx.fillRect(w.x + w.w - 4, w.y, 4, w.h);
292: 
293:     ctx.strokeStyle = 'rgba(4,6,5,0.55)';
294:     ctx.lineWidth = 1;
295:     ctx.strokeRect(w.x + 0.5, w.y + 0.5, w.w - 1, w.h - 1);
296: 
297:     if (metal) {
298:       ctx.strokeStyle = 'rgba(170,181,172,0.12)';
299:       ctx.lineWidth = 1;
300:       if (w.w > w.h) {
301:         for (let x = w.x + 14; x < w.x + w.w - 8; x += 26) line(ctx, x, w.y + 4, x, w.y + w.h - 4, 'rgba(170,181,172,0.12)', 1);
302:       } else {
303:         for (let y = w.y + 14; y < w.y + w.h - 8; y += 26) line(ctx, w.x + 4, y, w.x + w.w - 4, y, 'rgba(170,181,172,0.12)', 1);
304:       }
305:     } else {
306:       const count = Math.floor((w.w > w.h ? w.w : w.h) / 46);
307:       ctx.fillStyle = 'rgba(195,197,182,0.12)';
308:       for (let i = 0; i < count; i++) {
309:         const x = w.w > w.h ? w.x + 20 + i * 46 : w.x + w.w * 0.5;
310:         const y = w.w > w.h ? w.y + w.h * 0.5 : w.y + 20 + i * 46;
311:         ctx.beginPath();
312:         ctx.arc(x, y, 1.2, 0, TAU);
313:         ctx.fill();
314:       }
315:     }
316:   }
317: }
