330: function drawProp(ctx, p, r) {
331:   const x = p.x, y = p.y, w = p.w, h = p.h;
332:   const v = p.seed || 0.5;
333:   switch (p.type) {
334:     case 'crate': {
335:       shadow(ctx, p);
336:       ctx.fillStyle = v > 0.5 ? '#3d3323' : '#332c20';
