338:       ctx.strokeStyle = '#16120c';
339:       ctx.lineWidth = 3;
340:       ctx.strokeRect(x + 1.5, y + 1.5, w - 3, h - 3);
341:       ctx.strokeStyle = 'rgba(198,166,105,0.24)';
342:       ctx.lineWidth = 1;
343:       ctx.strokeRect(x + 6, y + 6, w - 12, h - 12);
344:       ctx.beginPath();
345:       ctx.moveTo(x + 7, y + h - 7);
346:       ctx.lineTo(x + w - 7, y + 7);
347:       ctx.stroke();
348:       ctx.fillStyle = 'rgba(210,187,133,0.18)';
349:       ctx.fillRect(x + 5, y + 5, w - 10, 2);
350:       ctx.fillStyle = 'rgba(16,12,8,0.5)';
351:       for (let i = 12; i < w - 8; i += 20) ctx.fillRect(x + i, y + h * 0.5 - 1, 9, 2);
352:       ctx.fillStyle = 'rgba(0,0,0,0.28)';
353:       ctx.fillRect(x + w - 8, y + 6, 3, h - 12);
354:       break;
355:     }
356:     case 'pallet': {
357:       ctx.fillStyle = 'rgba(0,0,0,0.24)';
358:       ctx.fillRect(x + 5, y + 5, w, h);
359:       ctx.fillStyle = '#2d271b';
360:       ctx.fillRect(x, y, w, h);
361:       ctx.fillStyle = '#4a3d27';
362:       for (let i = 0; i < 5; i++) ctx.fillRect(x + 5 + i * (w - 10) / 5, y + 4, (w - 10) / 7, h - 8);
363:       ctx.strokeStyle = 'rgba(8,7,4,0.6)';
364:       ctx.strokeRect(x, y, w, h);
365:       break;
366:     }
367:     case 'barrel': {
368:       ctx.fillStyle = 'rgba(0,0,0,0.45)';
369:       ellipse(ctx, x + w / 2 + 7, y + h / 2 + 9, w / 2, h / 2);
370:       ctx.fill();
371:       const g = ctx.createRadialGradient(x + w * 0.38, y + h * 0.32, 2, x + w / 2, y + h / 2, w / 2);
372:       g.addColorStop(0, v > 0.5 ? '#5a5540' : '#4d3e2c');
373:       g.addColorStop(1, '#1b1a15');
374:       ctx.fillStyle = g;
375:       ellipse(ctx, x + w / 2, y + h / 2, w / 2, h / 2);
376:       ctx.fill();
377:       ctx.strokeStyle = 'rgba(12,12,9,0.8)';
378:       ctx.lineWidth = 2;
379:       ctx.stroke();
380:       ctx.strokeStyle = 'rgba(207,183,116,0.22)';
381:       ctx.beginPath();
382:       ctx.ellipse(x + w / 2, y + h / 2, w * 0.35, h * 0.35, 0, 0, TAU);
383:       ctx.stroke();
384:       if (v > 0.6) {
385:         ctx.fillStyle = 'rgba(167,53,37,0.48)';
386:         ctx.beginPath();
387:         ctx.arc(x + w * 0.52, y + h * 0.48, w * 0.16, 0, TAU);
388:         ctx.fill();
389:       }
390:       break;
391:     }
392:     case 'locker': {
393:       shadow(ctx, p, 7);
394:       ctx.fillStyle = '#27312e';
395:       ctx.fillRect(x, y, w, h);
396:       ctx.strokeStyle = '#101615';
397:       ctx.lineWidth = 2;
398:       ctx.strokeRect(x + 1, y + 1, w - 2, h - 2);
399:       ctx.strokeStyle = 'rgba(156,175,163,0.18)';
400:       for (let i = 26; i < w; i += 30) line(ctx, x + i, y + 4, x + i, y + h - 4, 'rgba(156,175,163,0.18)', 1);
401:       ctx.fillStyle = 'rgba(200,196,170,0.4)';
402:       for (let i = 18; i < w; i += 30) ctx.fillRect(x + i, y + h * 0.48, 2, 8);
403:       break;
404:     }
405:     case 'shelf': {
406:       shadow(ctx, p, 7);
407:       ctx.fillStyle = '#1b201d';
408:       ctx.fillRect(x, y, w, h);
409:       ctx.strokeStyle = 'rgba(123,132,121,0.32)';
410:       ctx.lineWidth = 2;
411:       if (w > h) {
412:         for (let i = 0; i < 3; i++) line(ctx, x + 3, y + 7 + i * (h - 14) / 2, x + w - 3, y + 7 + i * (h - 14) / 2, 'rgba(123,132,121,0.32)', 2);
413:         for (let i = 12; i < w - 8; i += 34) {
