438:       ctx.fillRect(x, y, w, h);
439:       ctx.strokeStyle = 'rgba(150,170,164,0.3)';
440:       ctx.strokeRect(x + 2, y + 2, w - 4, h - 4);
441:       ctx.fillStyle = 'rgba(120,165,160,0.15)';
442:       ctx.fillRect(x + 8, y + 7, w - 16, h - 14);
