451:       ctx.strokeStyle = 'rgba(140,150,135,0.2)';
452:       ctx.lineWidth = 1;
453:       ctx.stroke();
454:       line(ctx, x + 12, y + h / 2, x + w - 12, y + h / 2, 'rgba(145,155,140,0.3)', 1.5);
