461:       ctx.strokeStyle = 'rgba(140,140,123,0.3)';
462:       ctx.lineWidth = 2;
463:       line(ctx, x + w / 2, y - 22, x + w / 2, y + 2, 'rgba(140,140,123,0.3)', 2);
464:       ctx.strokeStyle = 'rgba(182,182,160,0.45)';
