469:       const g = ctx.createLinearGradient(x, y, x + w, y + h);
470:       g.addColorStop(0, 'rgba(151,121,100,0.78)');
471:       g.addColorStop(0.5, 'rgba(116,86,70,0.82)');
472:       g.addColorStop(1, 'rgba(58,42,35,0.9)');
473:       ctx.fillStyle = g;
474:       ctx.beginPath();
475:       ctx.ellipse(x + w / 2, y + h * 0.58, w * 0.4, h * 0.43, 0, 0, TAU);
476:       ctx.fill();
477:       ctx.strokeStyle = 'rgba(44,24,20,0.75)';
478:       ctx.lineWidth = 1.4;
479:       for (let i = 0; i < 4; i++) {
480:         const yy = y + h * (0.34 + i * 0.12);
481:         ctx.beginPath();
482:         ctx.moveTo(x + w * 0.28, yy);
483:         ctx.quadraticCurveTo(x + w * 0.5, yy + 4, x + w * 0.72, yy);
484:         ctx.stroke();
485:       }
486:       ctx.fillStyle = 'rgba(104,25,20,0.5)';
487:       ctx.beginPath();
488:       ctx.ellipse(x + w / 2, y + h * 0.84, w * 0.18, 4, 0, 0, TAU);
