511:     case 'table': {
512:       shadow(ctx, p, 8);
513:       ctx.fillStyle = '#2e3937';
514:       ctx.fillRect(x, y, w, h);
515:       const g = ctx.createLinearGradient(0, y, 0, y + h);
516:       g.addColorStop(0, 'rgba(190,203,194,0.18)');
