522:       ctx.strokeRect(x + 3, y + 3, w - 6, h - 6);
523:       ctx.fillStyle = 'rgba(194,206,194,0.13)';
524:       ctx.fillRect(x + 6, y + 5, w - 12, 2);
525:       ctx.fillStyle = 'rgba(0,0,0,0.4)';
526:       ctx.fillRect(x + w * 0.24, y + h * 0.68, w * 0.4, 2);
527:       break;
528:     }
529:     case 'machine': {
530:       shadow(ctx, p, 10);
531:       ctx.fillStyle = '#252d2b';
532:       ctx.fillRect(x, y, w, h);
533:       ctx.strokeStyle = '#0f1412';
534:       ctx.lineWidth = 3;
535:       ctx.strokeRect(x + 1.5, y + 1.5, w - 3, h - 3);
536:       ctx.fillStyle = '#1a211f';
