  if (WORLD.w > halfW * 2) state.camera.x = clamp(state.camera.x, halfW, WORLD.w - halfW);
  else state.camera.x = WORLD.w / 2;
  if (WORLD.h > halfH * 2) state.camera.y = clamp(state.camera.y, halfH, WORLD.h - halfH);
